def parse_semver(v):
    if not valid_version(v):
        return None
    return tuple(int(x) for x in v.split('.'))

def extract_semver(version):
    if not isinstance(version, str):
        return None
    semver = version.split(':', 1)[1] if ':' in version else version
    if '+build.' in semver:
        semver = semver.split('+build.', 1)[0]
    return parse_semver(semver)

def semver_string(version):
    sv = extract_semver(version)
    if sv is None:
        return None
    return f"{sv[0]}.{sv[1]}.{sv[2]}"

def version_build_timestamp(version):
    if not isinstance(version, str) or '+build.' not in version:
        return None
    after = version.split('+build.', 1)[1]
    try:
        return int(after)
    except ValueError:
        return None

def compare_versions(a, b):
    sa = extract_semver(a)
    sb = extract_semver(b)
    if sa is not None and sb is not None:
        if sa != sb:
            return 1 if sa > sb else -1
        ta = version_build_timestamp(a)
        tb = version_build_timestamp(b)
        if ta is not None and tb is not None and ta != tb:
            return 1 if ta > tb else -1
